#include "Payment/Payment.h"
Payment::Payment():amount_vnd_(0),method_(PaymentMethod::CASH){} Payment::Payment(const std::string&id,const std::string&invoice,long long amount,PaymentMethod method,const std::string&paid):payment_id_(id),invoice_id_(invoice),paid_at_(paid),amount_vnd_(amount),method_(method){} const std::string& Payment::getPaymentId()const{return payment_id_;} const std::string& Payment::getInvoiceId()const{return invoice_id_;} long long Payment::getAmountVnd()const{return amount_vnd_;} PaymentMethod Payment::getMethod()const{return method_;} const std::string& Payment::getPaidAt()const{return paid_at_;}
